// Package lru implements a fixed-capacity least-recently-used cache.
//
// Entries live in a slice-backed doubly linked list addressed by index, which
// keeps every operation O(1) expected time and avoids a heap allocation per entry.
package lru

// nilIdx marks the absence of a neighbour in the recency list.
const nilIdx = -1

type entry[K comparable, V any] struct {
	key        K
	value      V
	prev, next int32
}

// Cache is an LRU cache holding at most a fixed number of entries.
// The zero value is not usable; create one with New. A Cache is not safe for
// concurrent use.
type Cache[K comparable, V any] struct {
	capacity int
	index    map[K]int32
	entries  []entry[K, V]
	free     []int32 // slots in entries released by Delete
	head     int32   // most recently used
	tail     int32   // least recently used
}

// New returns an empty cache that holds at most capacity entries.
// It panics if capacity is not positive.
func New[K comparable, V any](capacity int) *Cache[K, V] {
	if capacity <= 0 {
		panic("lru: capacity must be positive")
	}
	return &Cache[K, V]{
		capacity: capacity,
		index:    make(map[K]int32),
		head:     nilIdx,
		tail:     nilIdx,
	}
}

// Len reports the number of entries in the cache.
func (c *Cache[K, V]) Len() int { return len(c.index) }

// Get returns the value stored for key and marks it most recently used.
func (c *Cache[K, V]) Get(key K) (V, bool) {
	i, ok := c.index[key]
	if !ok {
		var zero V
		return zero, false
	}
	c.moveToFront(i)
	return c.entries[i].value, true
}

// Set stores value for key and marks it most recently used. If the cache then
// exceeds its capacity, the least recently used entry is evicted.
func (c *Cache[K, V]) Set(key K, value V) {
	if i, ok := c.index[key]; ok {
		c.entries[i].value = value
		c.moveToFront(i)
		return
	}

	var i int32
	switch {
	case len(c.index) >= c.capacity:
		// Reuse the evicted tail's slot for the new entry.
		i = c.tail
		c.unlink(i)
		delete(c.index, c.entries[i].key)
	case len(c.free) > 0:
		i = c.free[len(c.free)-1]
		c.free = c.free[:len(c.free)-1]
	default:
		c.entries = append(c.entries, entry[K, V]{})
		i = int32(len(c.entries) - 1)
	}

	c.entries[i] = entry[K, V]{key: key, value: value, prev: nilIdx, next: nilIdx}
	c.index[key] = i
	c.pushFront(i)
}

// Delete removes key from the cache and reports whether it was present.
func (c *Cache[K, V]) Delete(key K) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.unlink(i)
	delete(c.index, key)
	c.entries[i] = entry[K, V]{} // drop references so they can be collected
	c.free = append(c.free, i)
	return true
}

func (c *Cache[K, V]) moveToFront(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache[K, V]) pushFront(i int32) {
	e := &c.entries[i]
	e.prev = nilIdx
	e.next = c.head
	if c.head != nilIdx {
		c.entries[c.head].prev = i
	}
	c.head = i
	if c.tail == nilIdx {
		c.tail = i
	}
}

func (c *Cache[K, V]) unlink(i int32) {
	e := &c.entries[i]
	if e.prev != nilIdx {
		c.entries[e.prev].next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nilIdx {
		c.entries[e.next].prev = e.prev
	} else {
		c.tail = e.prev
	}
	e.prev, e.next = nilIdx, nilIdx
}

package lru

import "testing"

func TestEvictsLeastRecentlyUsed(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf(`Get("a") = %q, %v; want "1", true`, v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal(`Get("b") hit; want evicted`)
	}
	if got := c.Len(); got != 2 {
		t.Fatalf("Len() = %d, want 2", got)
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, ok := c.Get("a"); !ok || v != "9" {
		t.Fatalf(`Get("a") = %q, %v; want "9", true`, v, ok)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal(`Get("b") hit; want evicted`)
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New[int, int](3)
	for i := range 3 {
		c.Set(i, i)
	}
	if !c.Delete(1) || c.Delete(1) {
		t.Fatal("Delete(1) should succeed once")
	}
	c.Set(3, 3)
	c.Set(4, 4) // evicts 0
	if _, ok := c.Get(0); ok {
		t.Fatal("Get(0) hit; want evicted")
	}
	for _, k := range []int{2, 3, 4} {
		if v, ok := c.Get(k); !ok || v != k {
			t.Fatalf("Get(%d) = %d, %v", k, v, ok)
		}
	}
	if len(c.entries) != 3 {
		t.Fatalf("entries grew to %d, want 3", len(c.entries))
	}
}

func TestCapacityOne(t *testing.T) {
	c := New[string, int](1)
	c.Set("a", 1)
	c.Set("b", 2)
	if _, ok := c.Get("a"); ok {
		t.Fatal(`Get("a") hit; want evicted`)
	}
	if !c.Delete("b") || c.Len() != 0 {
		t.Fatal("Delete(b) failed")
	}
	c.Set("c", 3)
	if v, _ := c.Get("c"); v != 3 {
		t.Fatalf(`Get("c") = %d, want 3`, v)
	}
}

// Command app simulates an LRU cache driven by commands read from stdin.
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/internal/lru"
)

func main() {
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	err := run(os.Stdin, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

// run reads the capacity and commands from r and writes command results to w.
func run(r io.Reader, w *bufio.Writer) error {
	sc := bufio.NewScanner(bufio.NewReaderSize(r, 1<<16))
	sc.Buffer(make([]byte, 0, 4096), 1<<20)

	if !sc.Scan() {
		if err := sc.Err(); err != nil {
			return fmt.Errorf("read capacity: %w", err)
		}
		return errors.New("missing capacity")
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(sc.Bytes())))
	if err != nil || capacity < 1 {
		return fmt.Errorf("invalid capacity %q", sc.Bytes())
	}

	cache := lru.New[string, string](capacity)
	for sc.Scan() {
		cmd, rest, _ := bytes.Cut(bytes.TrimRight(sc.Bytes(), "\r"), []byte{' '})
		switch string(cmd) {
		case "SET":
			key, value, ok := bytes.Cut(rest, []byte{' '})
			if ok {
				cache.Set(string(key), string(value))
			}
		case "GET":
			if v, ok := cache.Get(string(rest)); ok {
				w.WriteString(v)
			} else {
				w.WriteString("NULL")
			}
			w.WriteByte('\n')
		case "DEL":
			if cache.Delete(string(rest)) {
				w.WriteString("1\n")
			} else {
				w.WriteString("0\n")
			}
		case "SIZE":
			w.Write(strconv.AppendInt(w.AvailableBuffer(), int64(cache.Len()), 10))
			w.WriteByte('\n')
		}
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("read commands: %w", err)
	}
	return nil
}
